6	static void expect_linear(Halfedge_Mesh& mesh, Halfedge_Mesh const &after) {
7		size_t numVerts = mesh.vertices.size();
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		// count the number of new edges to be generated after linear subdiv
12		// count the number of quad faces to be generated after linear subdiv
13		size_t ce = 0;
14		size_t cf = 0;
15		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
16			if (!f->boundary) {
17				ce += f->degree();
18				cf += f->degree() - 1;
19			}
20		}
21	
22		mesh.linear_subdivide();
23		if (auto msg = mesh.validate()) {
24			throw Test::error("Invalid mesh: " + msg.value().second);
25		}
26	
27		// check that all faces are degree 4
28		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
29			if (!f->boundary && f->degree() != 4) {
30				throw Test::error("Linear subdivision created a non-quad face!");
31			}
32		}
33	
34		// check for expected number of elements
35		if (numVerts + numEdges + numFaces - mesh.n_boundaries() != mesh.vertices.size()) {
36			throw Test::error("Linear subdivision did not create the expected number of vertices!");
37		}
38		if (numEdges * 2 + ce != mesh.edges.size()) {
39			throw Test::error("Linear subdivision did not create the expected number of edges!");
40		}
41		if (numFaces + cf != mesh.faces.size()) {
42			throw Test::error("Linear subdivision did not create the expected number of faces!");
43		}
44	
45		// check mesh shape:
46		if (auto diff = Test::differs(mesh, after)) {
47			throw Test::error("Result does not match expected: " + diff.value());
48		}
49	}
