7	Test test_a2_global_mix("a2.global.mix", []() {
8		RNG rng(2266524198);
9	
10		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 2));
11	
12		constexpr uint32_t operations = 10;
13	
14		for (uint32_t i = 0; i < operations; i++) {
15	
16			int32_t op = rng.integer(0, 4);
17	
18			switch (op) {
19			case 0: {
20				mesh.triangulate();
21			} break;
22			case 1: {
23				mesh.simplify(0.25f);
24			} break;
25			case 2: {
26				mesh.isotropic_remesh({3, 1.2f, 0.8f, 10, 0.2f});
27			} break;
28			case 3: {
29				int32_t type = rng.integer(0, 2);
30				if (type == 0)
31					mesh.loop_subdivide();
32				else if (type == 1)
33					mesh.linear_subdivide();
34				else
35					mesh.catmark_subdivide();
36			} break;
37			default: die("Got bad random operation?");
38			}
39	
40			if (auto msg = mesh.validate()) {
41				throw Test::error("Invalid mesh after operation " + std::to_string(op) + " with seed " +
42				                  std::to_string(rng.get_seed()) + ": " + msg.value().second);
43			}
44		}
45	});
